query:
{
  donatedEvents(first: 10, orderBy: blockTimestamp, orderDirection: desc) {
    id
    donor
    amount
    totalDonation
    blockTimestamp
  }
  borrowedEvents(first: 10, orderBy: blockTimestamp, orderDirection: desc) {
    id
    borrower
    amount
    totalBorrowing
    blockTimestamp
  }
}
